-- tipo: SQL | Grava a premissa historica do gestor (percentual/modo/justificativa) por CICLO+CR+CONTA. INSERT ... ON DUPLICATE KEY UPDATE: atomico, imune a save concorrente. Params: cicloId, crId, contaId, percentual, modo, justificativa, agora
INSERT INTO HIST_PREMISSA (CICLO_ID, CR_ID, CONTA_ID, PERCENTUAL, MODO, JUSTIFICATIVA, CRIADO_EM) VALUES ({{cicloId}}, {{crId}}, {{contaId}}, {{percentual}}, '{{modo}}', '{{justificativa}}', '{{agora}}') ON DUPLICATE KEY UPDATE PERCENTUAL = VALUES(PERCENTUAL), MODO = VALUES(MODO), JUSTIFICATIVA = VALUES(JUSTIFICATIVA), CRIADO_EM = VALUES(CRIADO_EM)